return {["fb31_01"]={["dsc"]=[[你来到了水塘边。好险差点掉进了池塘，东面传来隐隐的灯光。]],["id"]=[[fb31_01]],["item1"]=[[fb31item16]],["leftUp"]=[[fb31_05]],["name"]=[[水塘]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb31_02"]={["dsc"]=[[这里是内室，较为气闷。此内室甚是安静，地上放着各式的竹签，竹签按奇怪位置分列，好像和奇门八卦暗合。]],["id"]=[[fb31_02]],["item1"]=[[fb31item12]],["name"]=[[内室]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb31_08]]},["fb31_03"]={["dsc"]=[[这里是大理城南边，远处可以隐约看到大理城的模样。]],["id"]=[[fb31_03]],["name"]=[[大理城南]],["permission"]=1,["right"]=[[fb31_04]],["stepMusic"]=[[jiaobu]]},["fb31_04"]={["dsc"]=[[这是一片茂密的矮树林。地上长满了长草，走在其间不见人烟，矮树林中还不时可以听到大自然发出的声响。]],["id"]=[[fb31_04]],["item1"]=[[fb31item13]],["left"]=[[fb31_03]],["name"]=[[矮树林]],["permission"]=1,["right"]=[[fb31_05]],["rightUp"]=[[fb31_09]],["role1"]=[[fb30r04_1]],["role2"]=[[fb30r04_2]],["stepMusic"]=[[jiaobu]]},["fb31_05"]={["dsc"]=[[你置身泥潭中，四周静悄悄的，四处散发着腐败的气味，赶紧早找出路，离开泥潭为好。]],["fightBackground"]=[[山内]],["id"]=[[fb31_05]],["left"]=[[fb31_04]],["name"]=[[泥潭]],["permission"]=2,["right"]=[[fb31_06]],["rightDown"]=[[fb31_01]],["stepMusic"]=[[jiaobu]]},["fb31_06"]={["dsc"]=[[这是一片茂密的黑森林。很多棵几十丈高的大树聚在一块，像一把把琼天大伞，连日月都被遮蔽得黯然无光。黑森林中阴森恐怖。]],["fightBackground"]=[[山内]],["id"]=[[fb31_06]],["item1"]=[[fb31item101]],["left"]=[[fb31_05]],["name"]=[[黑森林]],["permission"]=2,["right"]=[[fb31_07]],["stepMusic"]=[[jiaobu]]},["fb31_07"]={["dsc"]=[[这里是荒郊的一处茅屋。透过墙壁可以隐隐看到一丝灯光，一扇大门紧锁着，周围是高高的围墙。一切都很干净，并没有积多少灰尘。]],["id"]=[[fb31_07]],["left"]=[[fb31_06]],["name"]=[[茅屋大门]],["permission"]=2,["rightUp"]=[[fb31_10]],["stepMusic"]=[[jiaobu]]},["fb31_08"]={["down"]=[[fb31_02]],["dsc"]=[[这是一个小茅屋，桌上点着蜡烛。屋中只有一桌一床，陈设简单，却十分干净。床上铺着被褥。]],["fightBackground"]=[[山内]],["id"]=[[fb31_08]],["leftUp"]=[[fb31_10]],["name"]=[[茅屋]],["permission"]=1,["role1"]=[[fb30r08_1]],["role2"]=[[fb30r08_2]],["stepMusic"]=[[jiaobu]]},["fb31_09"]={["dsc"]=[[这是一条从山崖向横突出的小道，长约二丈余，三面无所凭依，除非有绝高胆色的人，普通人一般都不敢通过。]],["fightBackground"]=[[山内]],["id"]=[[fb31_09]],["leftDown"]=[[fb31_04]],["name"]=[[羊肠小道]],["permission"]=1,["rightUp"]=[[fb31_11]],["stepMusic"]=[[jiaobu]]},["fb31_10"]={["dsc"]=[[你走在一片实土地上。心理踏实多了，西面传来隐隐灯光。]],["fightBackground"]=[[山内]],["id"]=[[fb31_10]],["leftDown"]=[[fb31_07]],["name"]=[[实土地]],["permission"]=1,["rightDown"]=[[fb31_08]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb31_11"]={["dsc"]=[[这是一条陡峭的山路，连山羊都不一定上去。]],["fightBackground"]=[[山外]],["id"]=[[fb31_11]],["leftDown"]=[[fb31_09]],["name"]=[[陡路]],["permission"]=1,["rightUp"]=[[fb31_12]],["stepMusic"]=[[jiaobu]]},["fb31_12"]={["dsc"]=[[这里是一处峡谷，每年雨季山洪爆发时就形成了一处蔚为壮观的瀑布。大瀑布一泄千里，震撼人心。]],["id"]=[[fb31_12]],["item1"]=[[fb31item1]],["leftDown"]=[[fb31_11]],["name"]=[[大瀑布]],["permission"]=1,["role1"]=[[fb30r12_1]],["stepMusic"]=[[jiaobu]]},["fb31_13"]={["dsc"]=[[一叶铁舟，最多也就能载俩个人。舟通体是铁制的，连桨也是铁的。]],["id"]=[[fb31_13]],["item1"]=[[fb31item3]],["name"]=[[铁舟]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb31_14"]={["dsc"]=[[这是因山势而形成的天然喷泉，天然的毫无人工的痕迹。]],["id"]=[[fb31_14]],["item1"]=[[fb31item4]],["name"]=[[喷泉]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb31_15"]={["dsc"]=[[这是一条溪水，前面一片湖水，原来这就是瀑布和喷泉的源头。]],["id"]=[[fb31_15]],["item1"]=[[fb31item5]],["item2"]=[[2019qxhdd1]],["name"]=[[溪水]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb31_16"]={["dsc"]=[[这里是无名之山的无名之庙。正中供奉着如来三宝，左右各是文殊、普贤菩萨。一群青衣小和尚们正在佛像前的地上诵经。]],["id"]=[[fb31_16]],["item1"]=[[fb31item8]],["item2"]=[[fb31item8]],["name"]=[[寺庙]],["permission"]=1,["right"]=[[fb31_17]],["role1"]=[[fb30r16_1]],["role2"]=[[fb30r16_2]],["role3"]=[[fb30r16_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb31_22]]},["fb31_17"]={["dsc"]=[[山道从此断开，有几个突出的石梁，但是有个书生坐在其中石梁之上，如果有人要经过，就必须书生的同意！]],["id"]=[[fb31_17]],["left"]=[[fb31_16]],["name"]=[[石梁]],["permission"]=1,["right"]=[[fb31_18]],["role1"]=[[fb30r17_1]],["stepMusic"]=[[jiaobu]]},["fb31_18"]={["dsc"]=[[这里是陡峭的山路。一般人不会到这里来，不小心很容易便会跌堕到崖谷之中。]],["fightBackground"]=[[山外]],["id"]=[[fb31_18]],["left"]=[[fb31_17]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb31_19]],["stepMusic"]=[[jiaobu]]},["fb31_19"]={["dsc"]=[[这里是陡峭的山坡。此处山势陡峭，登山的人一个不小心很容易便会跌堕到崖谷之中。]],["fightBackground"]=[[山外]],["id"]=[[fb31_19]],["left"]=[[fb31_18]],["name"]=[[山坡]],["permission"]=1,["right"]=[[fb31_20]],["role1"]=[[fb30r19_1]],["stepMusic"]=[[jiaobu]]},["fb31_20"]={["dsc"]=[[过了峰顶忽然一片开阔的山地，平坦如砥。]],["id"]=[[fb31_20]],["item1"]=[[fb31item6]],["left"]=[[fb31_19]],["name"]=[[平地]],["permission"]=1,["right"]=[[fb31_21]],["role1"]=[[fb30r20_1]],["stepMusic"]=[[jiaobu]]},["fb31_21"]={["dsc"]=[[这里是无名的山岭的峰顶，怪石攒簇，最高的地方一石卓立，有擎天之势。]],["id"]=[[fb31_21]],["item1"]=[[fb31item21]],["item2"]=[[fb31item100]],["item3"]=[[fb31item102]],["left"]=[[fb31_20]],["name"]=[[峰顶]],["permission"]=1,["role1"]=[[fb31r21_100]],["role2"]=[[fb31r21_101]],["role3"]=[[fb31r21_102]],["stepMusic"]=[[jiaobu]]},["fb31_22"]={["down"]=[[fb31_16]],["dsc"]=[[这里是小寺庙的大殿。殿内香烟燎绕，幔角叮咚。香火旺盛的。正前方供着个大肚子，似乎永远都笑咪咪的弥勒佛。四大天王分列两旁，分执“风调雨顺”。]],["id"]=[[fb31_22]],["name"]=[[大殿]],["permission"]=1,["right"]=[[fb31_23]],["stepMusic"]=[[jiaobu]]},["fb31_23"]={["dsc"]=[[面前是一片荷塘，塘中荷花开的很盛，让人不禁想起一句诗接天莲叶无穷碧，映日荷花别样红，塘中有许多活蹦乱跳的鲤鱼。时而跳出水面，时而沉下水底。]],["id"]=[[fb31_23]],["item1"]=[[fb31item15]],["left"]=[[fb31_22]],["name"]=[[荷塘]],["permission"]=1,["right"]=[[fb31_24]],["role1"]=[[fb31r23_1]],["stepMusic"]=[[jiaobu]]},["fb31_24"]={["dsc"]=[[这是一片茂密的青竹林，一走进来，你仿佛迷失在竹的海洋中，真是一处隐居的好地方。]],["fightBackground"]=[[森林内]],["id"]=[[fb31_24]],["item1"]=[[fb31item11]],["item2"]=[[fb31item9]],["item3"]=[[fb31item9]],["item4"]=[[fb31item9]],["left"]=[[fb31_23]],["name"]=[[竹林]],["permission"]=1,["role1"]=[[fb31item9]],["role2"]=[[fb31item10]],["role3"]=[[fb31item9]],["role4"]=[[fb31item9]],["stepMusic"]=[[jiaobu]]},["fb31_25"]={["dsc"]=[[这是一间干净的石室，陈设十分简陋。靠墙放了一张小木床，地下几张蒲团，有两人坐在上面，眼睛微闭，好像睡去一般。]],["id"]=[[fb31_25]],["item1"]=[[fb31item8]],["item2"]=[[fb31item8]],["left"]=[[fb31_24]],["name"]=[[石室]],["permission"]=1,["role1"]=[[fb30r25_1]],["role2"]=[[fb30r25_2]],["stepMusic"]=[[jiaobu]]},["fb31_26"]={["down"]=[[fb31_24]],["dsc"]=[[这是一间很大的厢房，陈设十分简陋。靠墙放了几张小木床，西边有张床是空的，你蹑手蹑脚地走了过去。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb31_26]],["item1"]=[[fb31item14]],["name"]=[[厢房]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb31_27"]={["dsc"]=[[这是个阴暗的密室，墙上的油灯发出昏暗的黄光。]],["id"]=[[fb31_27]],["name"]=[[密室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb31_28]]},["fb31_28"]={["down"]=[[fb31_27]],["dsc"]=[[这是个阴暗的密室，墙上的油灯发出昏暗的黄光。]],["id"]=[[fb31_28]],["item1"]=[[wabaorenwu1]],["name"]=[[密室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb31_29]]},["fb31_29"]={["down"]=[[fb31_28]],["dsc"]=[[这是个阴暗的密室，墙上的油灯发出昏暗的黄光。]],["id"]=[[fb31_29]],["item1"]=[[wabaorenwu14]],["name"]=[[密室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb31_30]]},["fb31_30"]={["down"]=[[fb31_29]],["dsc"]=[[这是个阴暗的密室，墙上的油灯发出昏暗的黄光。]],["id"]=[[fb31_30]],["item1"]=[[wabaorenwu18]],["name"]=[[密室]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}00000000000000